(()=>{
"use strict";
const SEED=JSON.parse(document.getElementById("seed").textContent), KEY="ccc_mvp_v1";
let S=load(), U={view:"dashboard", projectId:S.selectedProjectId||"PARDIS", section:"overview", calY:1405, calM:7, production:"kanban", team:"members", analytics:"overview", modal:null, search:"", projectTab:"active"};
const WORK=["Scenario Ready","Script Approved","Shot List Ready","Filming","Editing","Review","Approved","Published"], DAYS=["شنبه","یکشنبه","دوشنبه","سه‌شنبه","چهارشنبه","پنجشنبه","جمعه"], MONTHS=["فروردین","اردیبهشت","خرداد","تیر","مرداد","شهریور","مهر","آبان","آذر","دی","بهمن","اسفند"], CTYPES=["Reel","Post","Story","Campaign","Event","YouTube","TikTok","Website"];
function load(){try{return JSON.parse(localStorage.getItem(KEY))||structuredClone(SEED)}catch{return structuredClone(SEED)}} function save(){localStorage.setItem(KEY,JSON.stringify(S))}
function cur(){return S.users.find(x=>x.id===S.currentUserId)||S.users[0]} function roles(){return cur().roles||[]} function admin(){return roles().includes("Admin")} function manager(){return admin()||roles().includes("Manager")} function perm(p){if(admin())return true;const map={overview:["Manager","Creator","Viewer","Content Manager","Script Writer","Videographer","Editor"],calendar:["Manager","Creator","Viewer","Content Manager","Script Writer","Videographer","Editor"],scenarios:["Manager","Script Writer","Content Manager"],production:["Manager","Creator","Content Manager","Script Writer","Videographer","Editor"],stories:["Manager","Creator","Viewer","Content Manager","Script Writer","Videographer","Editor"],campaign:["Manager","Content Manager"],analytics:["Manager"],team:["Manager"],export:["Manager"]};return (map[p]||[]).some(r=>roles().includes(r))}
function canProj(pid){return admin()||(cur().projects||[]).includes(pid)} function P(){return S.projects.find(p=>p.id===U.projectId)||S.projects[0]} function PC(){return S.content.filter(c=>c.projectId===U.projectId&&!c.archived)} function PS(){return S.scenarios.filter(c=>c.projectId===U.projectId)} function esc(x=""){return String(x).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#039;"}[c]))}
function jparts(d){let a=new Intl.DateTimeFormat("fa-IR-u-ca-persian",{year:"numeric",month:"numeric",day:"numeric"}).formatToParts(d).filter(x=>x.type!=="literal");return Object.fromEntries(a.map(x=>[x.type,+x.value]))} function jp(d){let p=jparts(d);return `${p.year}/${String(p.month).padStart(2,"0")}/${String(p.day).padStart(2,"0")}`} function jmonth(y,m){let a=[],start=new Date(Date.UTC(y+621,0,1,12));for(let i=-120;i<430;i++){let d=new Date(start);d.setUTCDate(d.getUTCDate()+i);let p=jparts(d);if(p.year===y&&p.month===m)a.push(d)}return a} function parseJ(s){if(!s)return null;let [y,m,d]=s.split("/").map(Number),a=jmonth(y,m);return a.find(x=>jparts(x).day===d)||null} function diff(s){let d=parseJ(s);if(!d)return "";let n=d-Date.now(),ad=Math.abs(n),days=Math.floor(ad/86400000),hrs=Math.floor((ad%86400000)/3600000),min=Math.floor((ad%3600000)/60000);return n<0?`${days} روز گذشته`:days?`${days} روز و ${hrs} ساعت مانده`:hrs?`${hrs} ساعت و ${min} دقیقه مانده`:min?`${min} دقیقه مانده`:"اکنون"}
function fmtTime(){return new Intl.DateTimeFormat("fa-IR",{hour:"2-digit",minute:"2-digit",second:"2-digit"}).format(new Date())} function todayText(){return new Intl.DateTimeFormat("fa-IR-u-ca-persian",{weekday:"long",year:"numeric",month:"long",day:"numeric"}).format(new Date())}
function progress(pid){let a=S.content.filter(c=>c.projectId===pid&&!c.archived);if(!a.length)return 0;return Math.round(a.reduce((n,c)=>n+((WORK.indexOf(c.status)+1)/WORK.length*100),0)/a.length)}
function log(action,pid=U.projectId){S.activityLog.unshift({id:"LOG-"+Date.now(),projectId:pid,projectName:S.projects.find(p=>p.id===pid)?.name||"—",date:jp(new Date()),time:fmtTime(),userName:cur().name,userId:cur().id,action})}
function notify(text,targetId){S.notifications.unshift({id:"NT-"+Date.now(),text,read:false,targetType:"content",targetId})}
function commit(msg){save(); toast(msg||"ذخیره شد"); render()} function toast(t){let x=document.createElement("div");x.className="toast";x.textContent=t;document.body.appendChild(x);setTimeout(()=>x.remove(),1300)}
function badge(t){return `<span class="badge">${esc(t)}</span>`}
function stat(label,val,extra=""){return `<div class="stat card"><small>${esc(label)}</small><strong>${esc(val)}</strong><span>${esc(extra)}</span></div>`}
function page(title,sub,actions=""){return `<div class="page-title"><div><h1>${esc(title)}</h1><p>${esc(sub||"")}</p></div><div class="actions">${actions}</div></div>`}
function btn(t,a,c="primary"){return `<button class="btn ${c}" data-act="${esc(a)}">${t}</button>`}
function empty(title,sub,act){return `<div class="empty card"><div class="empty-art">✦</div><h3>${esc(title)}</h3><p>${esc(sub)}</p>${act?btn(act.label,act.action):""}</div>`}
function render(){document.documentElement.dataset.theme=S.theme;document.documentElement.dataset.font=S.fontSize;document.getElementById("app").innerHTML=`<div class="shell ${S.sidebarOpen===false?"collapsed":""}">${sidebar()}<main><header>${header()}</header><div class="wrap">${U.view==="dashboard"?dashboard():U.view==="projects"?projects():U.view==="team"?team():U.view==="export"?exportsPage():settings()}</div></main>${modal()}</div>`;bind()}
function sidebar(){return `<aside class="sidebar"><div class="brand"><div class="logo">CC</div><div><strong>Content Control Center</strong><small>Content Operations MVP</small></div></div><button class="collapse" data-act="toggle">☰</button><nav>${[["dashboard","⌂","Dashboard"],["projects","▦","Projects"],["team","◉","Team Management"],["export","⇩","Export Center"],["settings","⚙","Settings"]].map(x=>`<button class="nav ${U.view===x[0]?"on":""}" data-act="nav:${x[0]}"><span>${x[1]}</span><b>${x[2]}</b></button>`).join("")}</nav><div class="side-user"><div class="avatar">${esc(cur().name[0])}</div><div><strong>${esc(cur().name)}</strong><small>${esc(roles().join(" / "))}</small></div></div></aside>`}
function header(){return `<div class="date"><span>${esc(todayText())}</span><b>${fmtTime()}</b></div><div class="head-tools"><button class="home" data-act="nav:projects">Home</button><button class="switcher" data-act="project-switcher">${esc(P()?.name||"Projects")}⌄</button><button class="search" data-act="search">⌕ <span>${U.search?esc(U.search):"جست‌وجوی سراسری"}</span><kbd>Ctrl K</kbd></button></div><div class="head-right"><button class="icon" data-act="notifications">●</button><button class="profile" data-act="profile">${esc(cur().name)}⌄</button></div>`}
function dashboard(){let accessible=S.projects.filter(p=>!p.archived&&canProj(p.id)), stats=[stat("Active Projects",accessible.length),stat("Total Reels",S.content.filter(c=>c.type==="Reel"&&canProj(c.projectId)&&!c.archived).length)];if(roles().includes("Videographer"))stats.push(stat("Filmed This Month",PC().filter(c=>["Editing","Review","Approved","Published"].includes(c.status)).length));if(roles().includes("Editor"))stats.push(stat("Edited This Month",PC().filter(c=>["Review","Approved","Published"].includes(c.status)).length));stats.push(stat("Needs Follow-up",S.content.filter(c=>c.status==="Review"&&canProj(c.projectId)).length));return page("Dashboard","نمای کلی حساب و Projectهای قابل دسترسی",btn("New Project","new-project","secondary"))+`<section class="account card">${[["نام",S.profile.firstName+" "+S.profile.lastName],["شماره ورود",S.profile.phone],["AI Tokens",S.profile.aiTokens],["Subscription",S.profile.subscriptionDays+" روز"]].map(x=>`<div><small>${esc(x[0])}</small><strong>${esc(x[1])}</strong></div>`).join("")}</section><section class="stats">${stats.join("")}</section><div class="dash-grid"><section class="card pad"><div class="section-head"><div><h2>تقویم سالانه ${U.calY}</h2><small>شمسی • هفته از شنبه</small></div><div>${btn("‹","year:-1","secondary small")} ${btn("›","year:1","secondary small")}</div></div><div class="months">${MONTHS.map((m,i)=>{let n=S.content.filter(c=>canProj(c.projectId)&&c.deadline.startsWith(`${U.calY}/${String(i+1).padStart(2,"0")}`)).length;return `<button class="month" data-act="month:${i+1}"><strong>${m}</strong><span>${jmonth(U.calY,i+1).length} روز</span><div class="mini"><i style="width:${Math.min(100,n*12)}%"></i></div><small>${n} Deadline</small></button>`}).join("")}</div></section><section class="card pad"><div class="section-head"><h2>Projects</h2>${btn("New Project","new-project","primary small")}</div>${accessible.map(p=>`<button class="project-row" data-act="quick:${p.id}"><div class="picon" style="--a:${p.color}">${esc(p.name[0])}</div><div><strong>${esc(p.name)}</strong><small>${progress(p.id)}%</small><div class="progress"><i style="width:${progress(p.id)}%"></i></div></div><span>${progress(p.id)}%</span></button>`).join("")||empty("پروژه‌ای نیست","یک Project ایجاد کن.")}</section></div><section class="card pad"><div class="section-head"><h2>Upcoming</h2><small>3 Deadlines + Campaigns + Shooting</small></div><div class="upcoming">${S.content.filter(c=>!c.archived&&canProj(c.projectId)).sort((a,b)=>parseJ(a.deadline)-parseJ(b.deadline)).slice(0,3).map(c=>`<div><small>DEADLINE</small><strong>${esc(c.title)}</strong><span>${esc(c.deadline)}</span><em>${esc(diff(c.deadline))}</em></div>`).join("")}</div></section>`}
function projects(){if(U.workspace)return projectShell();let list=S.projects.filter(p=>U.projectTab==="active"?!p.archived:p.archived).filter(p=>canProj(p.id)||(p.archived&&manager()));return page("Projects","هر Project یک workspace مستقل است",btn("New Project","new-project"))+`<div class="tabs"><button class="${U.projectTab==="active"?"active":""}" data-act="ptab:active">Active</button><button class="${U.projectTab==="archived"?"active":""}" data-act="ptab:archived">Archived</button></div>${list.length?`<div class="cards3">${list.map(p=>`<div class="project-card card"><div class="pc-head"><div class="picon big" style="--a:${p.color}">${esc(p.name[0])}</div><div><h3>${esc(p.name)}</h3><p>${esc(p.description)}</p></div></div><div class="progress-row"><span>Progress</span><b>${progress(p.id)}%</b></div><div class="progress"><i style="width:${progress(p.id)}%"></i></div><div class="meta">${S.content.filter(c=>c.projectId===p.id&&!c.archived).length} Content • ${p.contentTypes.length} Types</div><div class="actions">${btn("Quick Overview","quick:"+p.id,"secondary small")}${p.archived?btn("Unarchive","unarchive:"+p.id,"secondary small"):manager()?btn("Archive","archive:"+p.id,"danger small"):""}</div></div>`).join("")}</div>`:empty("Archived / Active خالی است","موردی برای نمایش وجود ندارد.")}`}
function quick(pid){let p=S.projects.find(x=>x.id===pid),c=S.content.filter(x=>x.projectId===pid&&!x.archived).sort((a,b)=>parseJ(a.deadline)-parseJ(b.deadline)).slice(0,3);return `<div class="modal"><div class="modal-box"><div class="modal-head"><strong>Quick Overview</strong><button data-act="close">×</button></div><div class="modal-body"><div class="quick-title"><div class="picon big">${esc(p.name[0])}</div><div><h2>${esc(p.name)}</h2><small>Progress ${progress(pid)}%</small></div></div><div class="stats four">${stat("Total",S.content.filter(x=>x.projectId===pid&&!x.archived).length)}${stat("Published",S.content.filter(x=>x.projectId===pid&&x.status==="Published").length)}${stat("In Production",S.content.filter(x=>x.projectId===pid&&["Filming","Editing","Review"].includes(x.status)).length)}${stat("Pending",S.content.filter(x=>x.projectId===pid&&x.status!=="Published").length)}</div><div class="card inset"><h3>Next 3 Deadlines</h3>${c.map(x=>`<div class="line"><span><b>DEADLINE</b>${esc(x.title)}<small>${esc(x.deadline)}</small></span><em>${esc(diff(x.deadline))}</em></div>`).join("")}</div><div class="actions end">${btn("Open Project","openproject:"+pid)}${perm("production")?btn("Status","quick-status:"+pid,"secondary"):""}${manager()?btn("Assign","quick-assign:"+pid,"secondary"):""}</div></div></div></div>`}
function projectShell(){if(!canProj(U.projectId))return empty("Access denied","Project در دسترس نیست.");let p=P(),mods=[["overview","Overview"],["calendar","Calendar"],["scenarios","Scenarios"],["production","Production Room"],["stories","Stories"],["campaign","Campaign"],["analytics","Analytics"]].filter(x=>perm(x[0]));return `<div class="project-shell"><section class="project-head card"><div class="pc-head"><div class="picon big" style="--a:${p.color}">${esc(p.name[0])}</div><div><div class="crumb">Projects / ${esc(p.name)}</div><h2>${esc(p.name)}</h2><p>${esc(p.description)}</p></div></div><div class="head-progress"><small>Progress ${progress(p.id)}%</small><div class="progress"><i style="width:${progress(p.id)}%"></i></div>${manager()?btn("Edit","edit-project","secondary small"):""}</div></section><div class="project-nav">${mods.map(m=>`<button class="${U.section===m[0]?"active":""}" data-act="section:${m[0]}">${m[1]}</button>`).join("")}</div>${U.section==="overview"?projectOverview():U.section==="calendar"?calendar():U.section==="scenarios"?scenariosPage():U.section==="production"?production():U.section==="stories"?storiesPage():U.section==="campaign"?campaign():analytics()}</div>`}
function projectOverview(){let c=PC();return `<div class="stats four">${stat("Total Content",c.length)}${stat("Published",c.filter(x=>x.status==="Published").length)}${stat("In Production",c.filter(x=>["Filming","Editing","Review"].includes(x.status)).length)}${stat("Pending",c.filter(x=>x.status!=="Published").length)}</div>${roles().includes("Script Writer")?`<div class="mini stat-inline">${stat("Scenarios",PS().length,"role-specific")}</div>`:""}<div class="dash-grid"><section class="card pad"><div class="section-head"><div><h3>Overall Trend</h3><small>Progress + weekly status + previous month</small></div></div><div class="chart"><svg viewBox="0 0 600 180" preserveAspectRatio="none"><polyline fill="none" stroke="currentColor" stroke-width="3" points="20,140 160,116 300,94 440,70 580,58"/></svg><div class="chart-labels"><span>هفته ۱</span><span>هفته ۲</span><span>هفته ۳</span><span>هفته ۴</span><span>هفته ۵</span></div></div></section><section class="card pad"><div class="section-head"><h3>Upcoming</h3></div>${c.sort((a,b)=>parseJ(a.deadline)-parseJ(b.deadline)).slice(0,4).map(x=>`<div class="line"><span><b>DEADLINE</b>${esc(x.title)}<small>${esc(x.deadline)}</small></span><em>${esc(diff(x.deadline))}</em></div>`).join("")}</section></div>`}
function calendar(){let ds=jmonth(U.calY,U.calM),first=ds[0],offset=[6,0,1,2,3,4,5][first.getUTCDay()],cells=Array(35).fill(null);ds.forEach(d=>{let p=jparts(d),i=offset+p.day-1;if(i<35)cells[i]=d});return `<div class="toolbar"><div class="seg"><button data-act="calprev">‹</button><strong>${MONTHS[U.calM-1]} ${U.calY}</strong><button data-act="calnext">›</button></div><div class="actions">${btn("Today","today","secondary small")}${btn("Month","calmode:month",U.calMode==="month"?"primary small":"secondary small")}${btn("Week","calmode:week","secondary small")}${btn("Day Detail","daydetail","secondary small")}${btn("＋ Content","new-content","primary small")}</div></div><div class="calendar">${DAYS.map(d=>`<div class="cal-head">${d}</div>`).join("")}${cells.map(d=>{if(!d)return `<div class="cell empty"></div>`;let key=jp(d),items=PC().filter(c=>c.deadline===key||c.publishDate===key),cams=S.campaigns.filter(c=>c.projectId===U.projectId&&parseJ(c.startDate)<=d&&parseJ(c.endDate)>=d);return `<div class="cell" data-date="${key}"><div class="day"><strong>${jparts(d).day}</strong>${S.showGregorian?`<small>${d.toISOString().slice(0,10)}</small>`:""}</div>${cams.map(c=>`<div class="event campaign">CAMPAIGN · ${esc(c.title)}</div>`).join("")}${items.map(c=>`<div class="event" draggable="true" data-drag="${c.id}"><div class="event-head"><strong>${esc(c.title)}</strong>${badge(c.status)}</div><div class="deadline"><small>DEADLINE</small><b>${esc(c.deadline)}</b><em>${esc(diff(c.deadline))}</em></div><small>${esc(S.users.find(u=>u.id===c.responsibleId)?.name||"")}</small></div>`).join("")}</div>`}).join("")}</div>`}
function scenariosPage(){let list=PS();return page("Scenarios","Project-only Scenario Library",manager()||roles().includes("Script Writer")?btn("New Scenario","new-scenario"):"")+`<div class="filters"><input placeholder="Search all text & metadata" data-search value="${esc(U.search)}"><select><option>All Status</option><option>Draft</option><option>Ready</option><option>Archived</option></select></div><div class="cards3">${list.filter(s=>!U.search||JSON.stringify(s).toLowerCase().includes(U.search.toLowerCase())).map(s=>`<div class="scenario-card card"><div class="section-head"><span>${esc(s.contentType)}</span>${badge(s.status)}</div><h3>${esc(s.title)}</h3><div class="progress-row"><span>Progress</span><b>${s.progress}%</b></div><div class="progress"><i style="width:${s.progress}%"></i></div><p>${esc(S.users.find(u=>u.id===s.responsibleId)?.name||"")}</p><div class="actions">${btn("Open","open-scenario:"+s.id,"secondary small")}${perm("scenarios")?btn("Edit","edit-scenario:"+s.id,"secondary small"):""}</div></div>`).join("")}</div>`}
function production(){let c=PC();return page("Production Room","Full team • role-aware workflow",perm("production")?btn("＋ Content","new-content"):"")+`<div class="filters"><input placeholder="Search" data-prod-search value="${esc(U.search)}"><select><option>All Status</option>${WORK.map(s=>`<option>${esc(s)}</option>`).join("")}</select><div class="toggle"><button class="${U.production==="kanban"?"active":""}" data-act="prod:kanban">Kanban</button><button class="${U.production==="table"?"active":""}" data-act="prod:table">Table</button></div></div>${U.production==="kanban"?`<div class="kanban">${WORK.map(st=>`<section><header><b>${esc(st)}</b><span>${c.filter(x=>x.status===st).length}</span></header>${c.filter(x=>x.status===st).map(prodCard).join("")||`<div class="empty-mini">خالی</div>`}</section>`).join("")}</div>`:`<div class="card table"><table><thead><tr><th>Title</th><th>Status</th><th>Deadline</th><th>Responsible</th><th>Roles</th></tr></thead><tbody>${c.map(x=>`<tr><td>${esc(x.title)}</td><td>${badge(x.status)}</td><td>${esc(x.deadline)}<small>${esc(diff(x.deadline))}</small></td><td>${esc(S.users.find(u=>u.id===x.responsibleId)?.name||"")}</td><td>${(x.roles||[]).length}</td></tr>`).join("")}</tbody></table></div>`}`}
function prodCard(c){return `<div class="prod card"><div class="event-head"><div><strong>${esc(c.title)}</strong><small>${esc(c.type)} • ${esc(S.users.find(u=>u.id===c.responsibleId)?.name||"")}</small></div>${badge(c.status)}</div><div class="deadline"><small>DEADLINE</small><b>${esc(c.deadline)}</b><em>${esc(diff(c.deadline))}</em></div><div class="roles">${(c.roles||[]).map(r=>`<span>${esc(r.role)}: ${esc(S.users.find(u=>u.id===r.userId)?.name||"")}</span>`).join("")}</div><div class="actions">${perm("production")?`<select data-status="${c.id}">${WORK.map(w=>`<option ${w===c.status?"selected":""}>${esc(w)}</option>`).join("")}</select>`:""}${btn("Open","open-content:"+c.id,"secondary small")}</div></div>`}
function storiesPage(){let a=S.stories.filter(x=>x.projectId===U.projectId);return page("Stories","Simple Story module • no frame editor",btn("New Story","new-story"))+`<div class="card table">${a.length?`<table><thead><tr><th>Title</th><th>Status</th><th>Deadline</th><th>Responsible</th><th>Publish</th></tr></thead><tbody>${a.map(x=>`<tr><td>${esc(x.title)}</td><td>${badge(x.status)}</td><td>${esc(x.deadline)}</td><td>${esc(S.users.find(u=>u.id===x.responsibleId)?.name||"")}</td><td>${esc(x.publishDate)}</td></tr>`).join("")}</tbody></table>`:empty("Story ثبت نشده","Storyها اینجا قرار می‌گیرند.")}</div>`}
function campaign(){let a=S.campaigns.filter(x=>x.projectId===U.projectId);return page("Campaign","Start / End Date • Planned / Active / Completed / Cancelled",btn("New Campaign","new-campaign"))+`<div class="cards3">${a.map(c=>`<div class="card scenario-card"><div class="section-head"><span>CAMPAIGN</span>${badge(c.status)}</div><h3>${esc(c.title)}</h3><p>${esc(c.startDate)} → ${esc(c.endDate)}</p><div class="roles">${(c.contentIds||[]).map(id=>`<span>${esc(S.content.find(x=>x.id===id)?.title||id)}</span>`).join("")||"No linked content"}</div><div class="actions">${btn("Edit","edit-campaign:"+c.id,"secondary small")}</div></div>`).join("")}</div>`}
function analytics(){let rs=S.analytics.filter(a=>PC().some(c=>c.id===a.contentId));return page("Analytics","Manual metrics • D0 / D1 / D3 / D7 / D30",btn("Add Metric","analytics-add"))+`<div class="tabs"><button class="${U.analytics==="overview"?"active":""}" data-act="analytics:overview">Overview</button><button class="${U.analytics==="compare"?"active":""}" data-act="analytics:compare">Compare</button><button class="${U.analytics==="reports"?"active":""}" data-act="analytics:reports">Reports</button></div>${U.analytics==="overview"?analyticsOverview(rs):U.analytics==="compare"?compare(rs):reports()}`}
function analyticsOverview(rs){return `<div class="dash-grid"><div class="card pad"><h3>Top / Low Performers</h3><div class="toplow"><div><small>TOP</small><strong>${esc(PC()[0]?.title||"—")}</strong></div><div><small>LOW</small><strong>${esc(PC().at(-1)?.title||"—")}</strong></div></div></div><div class="card pad"><h3>Global Analytics</h3><p>Aggregation and Project comparison available for accessible Projects.</p></div></div><div class="card table"><table><thead><tr><th>Content</th><th>D0</th><th>D1</th><th>D3</th><th>D7</th><th>D30</th></tr></thead><tbody>${rs.map(a=>`<tr><td>${esc(S.content.find(c=>c.id===a.contentId)?.title||a.contentId)}</td>${["D0","D1","D3","D7","D30"].map(d=>`<td>${a.metrics?.[d]?.Views||0}</td>`).join("")}</tr>`).join("")||`<tr><td colspan="6">No analytics data yet. Use Add Metric.</td></tr>`}</tbody></table></div>`}
function compare(rs){return `<div class="card pad"><div class="compare">${PC().map(c=>`<label><input type="checkbox" data-compare="${c.id}">${esc(c.title)}</label>`).join("")}</div>${btn("Compare","run-compare","primary")}</div>`}
function reports(){return `<div class="card pad"><h3>Report Builder</h3><div class="form2"><label>Period<select><option>Daily</option><option>Weekly</option><option>Monthly</option></select></label><label>Sections<select multiple><option selected>Analytics</option><option selected>Production</option><option>Calendar</option><option>Campaign</option></select></label></div><div class="actions">${btn("Export Report","print","secondary")}${btn("Generate Insight","ai","secondary")}${btn("Suggestions","ai","primary")}</div></div>`}
function team(){if(!manager())return empty("Access denied","فقط Admin و Manager.");return page("Team Management","Members + Activity Log",btn("Add Member","add-member"))+`<div class="tabs"><button class="${U.team==="members"?"active":""}" data-act="team:members">Members</button><button class="${U.team==="logs"?"active":""}" data-act="team:logs">Activity Log</button></div>${U.team==="members"?`<div class="card table"><table><thead><tr><th>User</th><th>Roles</th><th>Projects</th><th>User ID</th></tr></thead><tbody>${S.users.map(u=>`<tr><td>${esc(u.name)}<small>${esc(u.email)}</small></td><td>${u.roles.map(r=>badge(r)).join(" ")}</td><td>${u.projects.map(pid=>esc(S.projects.find(p=>p.id===pid)?.name||pid)).join(" • ")}</td><td>${esc(u.id)}</td></tr>`).join("")}</tbody></table></div>`:`<div class="card table"><table><thead><tr><th>Project</th><th>Date</th><th>Time</th><th>User</th><th>ID</th><th>Change</th></tr></thead><tbody>${S.activityLog.map(l=>`<tr><td>${esc(l.projectName)}</td><td>${esc(l.date)}</td><td>${esc(l.time)}</td><td>${esc(l.userName)}</td><td>${esc(l.userId)}</td><td>${esc(l.action)}</td></tr>`).join("")||`<tr><td colspan="6">No logs yet.</td></tr>`}</tbody></table></div>`}`}
function exportsPage(){return page("Export Center","Admin + Manager",btn("JSON Backup","export-json"))+`<div class="cards3"><div class="card pad"><h3>Project</h3><div class="actions">${btn("CSV","export-csv","secondary small")}${btn("PDF Print","print","secondary small")}${btn("JSON","export-json","secondary small")}</div></div><div class="card pad"><h3>Calendar</h3><div class="actions">${btn("CSV","export-calendar","secondary small")}${btn("PDF Print","print","secondary small")}</div></div><div class="card pad"><h3>Analytics</h3><div class="actions">${btn("CSV","export-analytics","secondary small")}${btn("PDF Print","print","secondary small")}</div></div><div class="card pad"><h3>Import / Reset</h3><div class="actions">${btn("Import JSON","import-json","secondary small")}${btn("Reset","reset","danger small")}</div></div></div>`}
function settings(){return page("Settings","Theme / Language / Date / Notifications")+`<div class="settings"><div class="card pad"><h3>Appearance</h3><label>Theme<select data-set="theme"><option value="dark" ${S.theme==="dark"?"selected":""}>Dark</option><option value="light" ${S.theme==="light"?"selected":""}>Light</option><option value="system" ${S.theme==="system"?"selected":""}>System</option></select></label><label>Font Size<select data-set="fontSize"><option value="small">Small</option><option value="medium" ${S.fontSize==="medium"?"selected":""}>Medium</option><option value="large">Large</option></select></label></div><div class="card pad"><h3>Language / Date</h3><label>Language<select><option>فارسی</option><option>English</option></select></label><label>Gregorian Display<select data-set="greg"><option value="false" ${!S.showGregorian?"selected":""}>Off</option><option value="true" ${S.showGregorian?"selected":""}>On</option></select></label></div><div class="card pad"><h3>Notifications</h3><button class="switch ${S.notificationsEnabled?"on":""}" data-act="notif-toggle"></button><p>Deadline 24h / Status / Review</p></div><div class="card pad"><h3>Developer Test Role</h3><select data-act="user-select">${S.users.map(u=>`<option value="${u.id}" ${u.id===S.currentUserId?"selected":""}>${esc(u.name)} — ${esc(u.roles.join(" / "))}</option>`).join("")}</select></div></div>`}
function modal(){if(!U.modal)return "";let m=U.modal;if(m.type==="quick")return quick(m.id);if(m.type==="project-switcher")return `<div class="modal"><div class="modal-box"><div class="modal-head"><strong>Switch Project</strong><button data-act="close">×</button></div><div class="modal-body">${S.projects.filter(p=>canProj(p.id)).map(p=>`<button class="switch-row" data-act="switch:${p.id}"><strong>${esc(p.name)}</strong><span>${progress(p.id)}%</span></button>`).join("")}</div></div></div>`;if(m.type==="notifications")return `<div class="modal"><div class="modal-box"><div class="modal-head"><strong>Notifications</strong><button data-act="close">×</button></div><div class="modal-body">${S.notifications.map(n=>`<button class="switch-row ${n.read?"read":""}" data-act="open-notif:${n.id}"><span>${n.read?"○":"●"}</span><strong>${esc(n.text)}</strong></button>`).join("")}</div></div></div>`;if(m.type==="profile")return `<div class="modal"><div class="modal-box smallbox"><div class="modal-head"><strong>Profile</strong><button data-act="close">×</button></div><div class="modal-body center"><div class="avatar lg">${esc(cur().name[0])}</div><h2>${esc(cur().name)}</h2><p>${esc(roles().join(" / "))}</p><p>${esc(S.profile.phone)}</p></div></div></div>`;if(m.type==="content")return contentDetail(m.id);if(m.type==="scenario")return scenarioDetail(m.id,m.edit);if(m.type==="new-project")return formProject();if(m.type==="new-content")return formContent();if(m.type==="new-scenario")return formScenario();if(m.type==="new-story")return formStory();if(m.type==="new-campaign")return formCampaign(m.id);if(m.type==="add-member")return formMember(m.id);if(m.type==="analytics")return formAnalytics(m.id);return ""}
function modalWrap(title,body){return `<div class="modal"><div class="modal-box"><div class="modal-head"><strong>${esc(title)}</strong><button data-act="close">×</button></div><div class="modal-body">${body}</div></div></div>`}
function contentDetail(id){let c=S.content.find(x=>x.id===id),s=S.scenarios.find(x=>x.id===c.scenarioId);return modalWrap(c.title,`<div class="crumb">Projects / ${esc(P().name)} / Content / ${esc(c.title)}</div><div class="detail-head"><div><h2>${esc(c.title)}</h2><div>${badge(c.status)} <span class="deadline-box"><small>DEADLINE</small><b>${esc(c.deadline)}</b><em>${esc(diff(c.deadline))}</em></span></div></div><div><small>${esc(S.users.find(u=>u.id===c.responsibleId)?.name||"")}</small><small>${esc(c.type)}</small></div></div><section class="detail-section"><h3>General Information</h3><div class="detail-grid">${[["Responsible",S.users.find(u=>u.id===c.responsibleId)?.name||""],["Publish Date",c.publishDate],["Project",P().name],["Content Type",c.type]].map(x=>`<div><small>${esc(x[0])}</small><strong>${esc(x[1])}</strong></div>`).join("")}</div>${perm("production")?`<label>Status<select data-status="${c.id}">${WORK.map(w=>`<option ${c.status===w?"selected":""}>${esc(w)}</option>`).join("")}</select></label>`:""}</section><section class="detail-section"><div class="section-head"><h3>Scenario</h3><div class="actions">${btn("Open","open-scenario:"+s.id,"secondary small")}${perm("scenarios")?btn("Edit","edit-scenario:"+s.id,"primary small"):""}</div></div><p>${esc(s.body.mainScript)}</p></section><section class="detail-section"><h3>Production</h3><div class="roles">${(c.roles||[]).map(r=>`<span>${esc(r.role)}: ${esc(S.users.find(u=>u.id===r.userId)?.name||"")}</span>`).join("")}</div><h4>Asset Links</h4>${(c.productionLinks||[]).map(l=>`<div class="link-row"><b>${esc(l.type)}</b><a href="${esc(l.url)}" target="_blank">Open</a><small>${esc(S.users.find(u=>u.id===l.addedBy)?.name||l.addedBy||"")} • ${esc(l.role||"")}</small></div>`).join("")||"No links"}<h4>Videographer → Editor Notes</h4>${(c.editorNotes||[]).map(n=>`<div class="note"><small>${esc(n.createdAt)}</small><p>${esc(n.text)}</p></div>`).join("")}${roles().includes("Videographer")||admin()||manager()?btn("Add Editor Note","note:"+c.id,"secondary small"):""}</section><section class="detail-section"><h3>Publishing</h3><div class="detail-grid">${[["Publish Date",c.publishDate],["Publish Time",c.publishTime||"—"],["Post URL",c.postUrl||"—"]].map(x=>`<div><small>${esc(x[0])}</small><strong>${esc(x[1])}</strong></div>`).join("")}</div></section><section class="comments"><h3>Comments</h3>${(c.comments||[]).map(x=>`<div class="comment"><div class="avatar">${esc(x.userName[0])}</div><div><strong>${esc(x.userName)}</strong><small>${esc(x.date)} ${esc(x.time)}</small><p>${esc(x.text)}</p></div></div>`).join("")||"No comments yet"}${roles().includes("Viewer")||manager()?`<div class="comment-add"><textarea data-comment="${c.id}" placeholder="Comment..."></textarea>${btn("Add Comment","comment:"+c.id)}</div>`:""}</section>`)}
function scenarioDetail(id,edit){let s=S.scenarios.find(x=>x.id===id);if(edit&&!perm("scenarios"))edit=false;if(!edit)return modalWrap(s.title,`<div class="crumb">Projects / ${esc(P().name)} / Scenarios / ${esc(s.title)}</div><div class="section-head"><h2>${esc(s.title)}</h2>${badge(s.status)}</div><div class="progress-row"><span>Progress</span><b>${s.progress}%</b></div><div class="progress"><i style="width:${s.progress}%"></i></div><section class="detail-section"><h3>Hooks</h3>${(s.hooks||[]).map((x,i)=>`<div class="option"><b>${i+1}</b><span>${esc(x)}</span></div>`).join("")}</section><section class="detail-section"><h3>Body</h3><p>${esc(s.body.mainScript)}</p><p>${esc(s.body.storyFlow)}</p><p>${esc(s.body.keyMessage)}</p><p>${esc(s.body.brandMention)}</p></section><section class="detail-section"><h3>CTA</h3>${(s.ctas||[]).map(x=>`<div class="option"><span>${esc(x)}</span></div>`).join("")}</section><section class="detail-section"><h3>Publishing</h3><p>${esc(s.publishing.caption)}</p><p>${esc(s.publishing.coverText)}</p><p>${esc(s.publishing.hashtags)}</p></section><section class="detail-section"><h3>Production</h3><p>Speaker: ${esc(s.production.speaker)}</p><p>${esc(s.light)}</p>${(s.production.editorNotes||[]).map(x=>`<p>• ${esc(x)}</p>`).join("")}</section><div class="ai"><button class="btn secondary" data-act="ai">Generate Scenario</button><button class="btn secondary" data-act="ai">Analyze / Improve</button></div>`);return modalWrap("Edit Scenario",scenarioEditor(s))}
function scenarioEditor(s){return `<div class="form2"><label>Title<input data-sf="title" value="${esc(s.title)}"></label><label>Content Type<select data-sf="contentType">${CTYPES.map(t=>`<option ${s.contentType===t?"selected":""}>${t}</option>`).join("")}</select></label><label>Goal<input data-sf="goal" value="${esc(s.goal)}"></label><label>Platform<input data-sf="platform" value="${esc(s.platform)}"></label><label>Publish Date<input data-sf="publishDate" value="${esc(s.publishDate)}"></label><label>Audience<input data-sf="audience" value="${esc(s.audience)}"></label><label>Content Pillar<input data-sf="contentPillar" value="${esc(s.contentPillar)}"></label><label>Responsible<select data-sf="responsibleId">${S.users.map(u=>`<option value="${u.id}" ${s.responsibleId===u.id?"selected":""}>${esc(u.name)}</option>`).join("")}</select></label></div><section class="detail-section"><div class="section-head"><h3>Hooks</h3>${btn("＋ Hook","addhook","secondary small")}</div><div id="hooks">${s.hooks.map((x,i)=>`<div class="array"><input data-hook="${i}" value="${esc(x)}"><button data-act="rmhook:${i}">×</button></div>`).join("")}</div></section><section class="detail-section"><h3>Body</h3><textarea data-body="mainScript">${esc(s.body.mainScript)}</textarea><textarea data-body="storyFlow">${esc(s.body.storyFlow)}</textarea><input data-body="keyMessage" value="${esc(s.body.keyMessage)}"><input data-body="brandMention" value="${esc(s.body.brandMention)}"></section><section class="detail-section"><div class="section-head"><h3>CTA</h3>${btn("＋ CTA","addcta","secondary small")}</div><div id="ctas">${s.ctas.map((x,i)=>`<div class="array"><input data-cta="${i}" value="${esc(x)}"><button data-act="rmcta:${i}">×</button></div>`).join("")}</div></section><section class="detail-section"><h3>Publishing</h3><input data-pub="caption" value="${esc(s.publishing.caption)}"><input data-pub="coverText" value="${esc(s.publishing.coverText)}"><input data-pub="hashtags" value="${esc(s.publishing.hashtags)}"><textarea data-pub="notes">${esc(s.publishing.notes)}</textarea></section><section class="detail-section"><h3>Production</h3><input data-prod="speaker" value="${esc(s.production.speaker)}"><textarea data-prod="editorNotes">${esc((s.production.editorNotes||[]).join("\n"))}</textarea></section><div class="actions end">${btn("Save Scenario","save-scenario:"+s.id)}${btn("AI Generate","ai","secondary")}${btn("AI Improve","ai","secondary")}</div>`}
function formProject(){return modalWrap("New Project",`<div class="form2"><label>Name<input data-p="name"></label><label>Description<input data-p="description"></label><label>Logo<input data-p="logo"></label><label>Color<input data-p="color" type="color" value="#7c5cff"></label></div><div class="card inset"><h4>Mode</h4><label><input type="radio" name="pm" value="blank" checked> Blank</label><label><input type="radio" name="pm" value="template"> Use Template</label><label><input type="radio" name="pm" value="import"> Import</label></div><div class="actions end">${btn("Save","save-project")}</div>`)}
function formContent(){return modalWrap("Create Content",`<div class="form2"><label>Title<input data-c="title"></label><label>Content Type<select data-c="type">${CTYPES.map(t=>`<option>${t}</option>`).join("")}</select></label><label>Status<select data-c="status">${WORK.map(t=>`<option>${t}</option>`).join("")}</select></label><label>Deadline<input data-c="deadline" value="1405/07/01"></label><label>Publish Date<input data-c="publishDate" value="1405/07/01"></label><label>Responsible<select data-c="responsibleId">${S.users.map(u=>`<option value="${u.id}">${esc(u.name)}</option>`).join("")}</select></label></div><div class="actions end">${btn("Save Content","save-content")}</div>`)}
function formScenario(){return modalWrap("New Scenario",`<div class="form2"><label>Title<input data-ns="title"></label><label>Content Type<select data-ns="contentType">${CTYPES.map(t=>`<option>${t}</option>`).join("")}</select></label><label>Goal<input data-ns="goal"></label><label>Platform<input data-ns="platform" value="Instagram"></label><label>Publish Date<input data-ns="publishDate" value="1405/07/01"></label><label>Audience<input data-ns="audience"></label><label>Content Pillar<input data-ns="contentPillar"></label><label>Responsible<select data-ns="responsibleId">${S.users.map(u=>`<option value="${u.id}">${esc(u.name)}</option>`).join("")}</select></label></div><input data-ns="hook" placeholder="At least 1 Hook"><textarea data-ns="body" placeholder="Main Script"></textarea><input data-ns="cta" placeholder="At least 1 CTA"><div class="actions end">${btn("Save Scenario","save-new-scenario")}</div>`)}
function formStory(){return modalWrap("New Story",`<div class="form2"><label>Title<input data-st="title"></label><label>Status<select data-st="status"><option>Scheduled</option><option>Production</option><option>Review</option><option>Published</option></select></label><label>Deadline<input data-st="deadline" value="1405/07/01"></label><label>Publish Date<input data-st="publishDate" value="1405/07/01"></label><label>Responsible<select data-st="responsibleId">${S.users.map(u=>`<option value="${u.id}">${esc(u.name)}</option>`).join("")}</select></label><label>Content/Reel<select data-st="contentId"><option value="">Optional</option>${PC().map(c=>`<option value="${c.id}">${esc(c.title)}</option>`).join("")}</select></label></div><div class="actions end">${btn("Save Story","save-new-story")}</div>`)}
function formCampaign(id){let c=id?S.campaigns.find(x=>x.id===id):null;return modalWrap(c?"Edit Campaign":"New Campaign",`<div class="form2"><label>Title<input data-ca="title" value="${esc(c?.title||"")}"></label><label>Status<select data-ca="status">${["Planned","Active","Completed","Cancelled"].map(x=>`<option ${c?.status===x?"selected":""}>${x}</option>`).join("")}</select></label><label>Start Date<input data-ca="startDate" value="${esc(c?.startDate||"1405/07/01")}"></label><label>End Date<input data-ca="endDate" value="${esc(c?.endDate||"1405/07/14")}"></label></div><div class="compare">${PC().map(x=>`<label><input type="checkbox" data-ca-content="${x.id}" ${c?.contentIds?.includes(x.id)?"checked":""}>${esc(x.title)}</label>`).join("")}</div><div class="actions end">${btn("Save","save-campaign:"+(c?.id||""))}</div>`)}
function formMember(id){let u=id?S.users.find(x=>x.id===id):null;return modalWrap(u?"Edit Member":"Add Member",`<div class="form2"><label>Name<input data-m="name" value="${esc(u?.name||"")}"></label><label>Email<input data-m="email" value="${esc(u?.email||"")}"></label><label>Roles<select multiple data-m="roles">${["Admin","Manager","Creator","Viewer","Content Manager","Script Writer","Videographer","Editor","Reviewer"].map(x=>`<option ${u?.roles.includes(x)?"selected":""}>${x}</option>`).join("")}</select></label><label>Projects<select multiple data-m="projects">${S.projects.map(x=>`<option value="${x.id}" ${u?.projects.includes(x.id)?"selected":""}>${esc(x.name)}</option>`).join("")}</select></label></div><div class="actions end">${btn("Save","save-member:"+(u?.id||""))}</div>`)}
function formAnalytics(id){let a=S.analytics.find(x=>x.contentId===id)||{contentId:id,metrics:{}};return modalWrap("Edit Analytics",`<div class="metric"><div>Metric</div>${["D0","D1","D3","D7","D30"].map(d=>`<div>${d}</div>`).join("")}${S.customMetrics.map(m=>`<label>${esc(m)}</label>${["D0","D1","D3","D7","D30"].map(d=>`<input type="number" data-metric="${d}|${m}" value="${a.metrics?.[d]?.[m]||0}">`).join("")}`).join("")}</div><textarea data-anote placeholder="Insight / Note"></textarea><div class="actions end">${btn("Save","save-analytics:"+id)}</div>`)}
function bind(){document.querySelectorAll("[data-act]").forEach(b=>b.onclick=()=>act(b.dataset.act));document.querySelectorAll("[data-status]").forEach(e=>e.onchange=()=>changeStatus(e.dataset.status,e.value));document.querySelectorAll("[data-set]").forEach(e=>e.onchange=()=>{let k=e.dataset.set;S[k]=k==="greg"?e.value==="true":e.value;commit("Setting saved")});document.querySelectorAll("[data-prod-search], [data-search]").forEach(e=>e.oninput=()=>{U.search=e.value;render()});document.querySelectorAll("[data-open-project]").forEach(e=>e.onclick=()=>quick(e.dataset.openProject));document.querySelectorAll("[data-drag]").forEach(e=>e.ondragstart=x=>x.dataTransfer.setData("text/plain",e.dataset.drag));document.querySelectorAll(".cell[data-date]").forEach(c=>{c.ondragover=e=>e.preventDefault();c.ondrop=e=>{e.preventDefault();let id=e.dataTransfer.getData("text/plain"),x=S.content.find(v=>v.id===id),d=c.dataset.date;if(x)confirmAct("Move Content",`${x.title} → ${d}`,()=>{x.publishDate=d;x.deadline=d;log("Deadline/Publish Date changed → "+d,x.projectId);commit("Content moved")})}})}
function act(a){if(a==="toggle"){S.sidebarOpen=S.sidebarOpen===false;save();render();return}if(a.startsWith("nav:")){U.view=a.slice(4);U.modal=null;U.projectId=S.selectedProjectId||U.projectId;U.section="overview";if(U.view!=="projects")U.workspace=false;render();return}if(a==="project-switcher"){U.modal={type:"project-switcher"};render();return}if(a==="notifications"){U.modal={type:"notifications"};render();return}if(a==="profile"){U.modal={type:"profile"};render();return}if(a==="search"){let q=prompt("Search accessible Projects / Content / Scenarios / Campaigns",U.search);if(q!==null){U.search=q;render()}return}if(a==="close"){U.modal=null;render();return}if(a==="new-project"){U.modal={type:"new-project"};render();return}if(a.startsWith("quick:")){U.modal={type:"quick",id:a.slice(6)};render();return}if(a.startsWith("openproject:")){U.projectId=a.slice(12);S.selectedProjectId=U.projectId;U.view="projects";U.workspace=true;U.modal=null;U.section="overview";save();render();return}if(a.startsWith("switch:")){U.projectId=a.slice(7);S.selectedProjectId=U.projectId;U.workspace=U.view==="projects";U.modal=null;save();render();return}if(a.startsWith("section:")){U.section=a.slice(8);U.view="projects";U.workspace=true;U.modal=null;render();return}if(a.startsWith("ptab:")){U.projectTab=a.slice(5);render();return}if(a.startsWith("year:")){U.calY+=+a.slice(5);render();return}if(a.startsWith("month:")){U.calM=+a.slice(6);U.modal=null;U.view="dashboard";U.modal={type:"month",month:U.calM};render();return}if(a==="calprev"){U.calM--;if(U.calM<1){U.calM=12;U.calY--}render();return}if(a==="calnext"){U.calM++;if(U.calM>12){U.calM=1;U.calY++}render();return}if(a==="today"){let p=jparts(new Date());U.calY=p.year;U.calM=p.month;render();return}if(a.startsWith("calmode:")){U.calMode=a.slice(8);S.viewPrefs.calendarMode=U.calMode;render();return}if(a==="daydetail"){U.modal={type:"month",month:U.calM};render();return}if(a==="new-content"){U.modal={type:"new-content"};render();return}if(a==="new-scenario"){U.modal={type:"new-scenario"};render();return}if(a==="new-story"){U.modal={type:"new-story"};render();return}if(a==="new-campaign"){U.modal={type:"new-campaign"};render();return}if(a.startsWith("open-content:")){U.modal={type:"content",id:a.slice(13)};render();return}if(a.startsWith("open-scenario:")){U.modal={type:"scenario",id:a.slice(14),edit:false};render();return}if(a.startsWith("edit-scenario:")){U.modal={type:"scenario",id:a.slice(14),edit:true};render();return}if(a.startsWith("quick-status:")){toast("Quick status action — Role based");return}if(a.startsWith("quick-assign:")){toast("Quick assign action — Role based");return}if(a.startsWith("archive:")){archive(a.slice(8),true);return}if(a.startsWith("unarchive:")){archive(a.slice(10),false);return}if(a==="edit-project"){toast("Project edit form can be added here");return}if(a.startsWith("duplicate-content:")){duplicate(a.slice(18));return}if(a.startsWith("note:")){let id=a.slice(5),t=prompt("Editor Note");if(t){let c=S.content.find(x=>x.id===id);c.editorNotes.push({userId:cur().id,text:t,createdAt:jp(new Date())+" "+fmtTime()});log("Videographer → Editor Note added",c.projectId);commit("Editor Note saved")}return}if(a.startsWith("comment:")){let id=a.slice(8),ta=document.querySelector(`[data-comment="${id}"]`),t=ta?.value.trim();if(t){let c=S.content.find(x=>x.id===id);c.comments.push({userName:cur().name,date:jp(new Date()),time:fmtTime(),text:t});log("Comment added",c.projectId);commit("Comment saved")}return}if(a==="addhook"){let s=S.scenarios.find(x=>x.id===U.modal.id);s.hooks.push("");render();return}if(a==="addcta"){let s=S.scenarios.find(x=>x.id===U.modal.id);s.ctas.push("");render();return}if(a.startsWith("rmhook:")){S.scenarios.find(x=>x.id===U.modal.id).hooks.splice(+a.slice(7),1);render();return}if(a.startsWith("rmcta:")){S.scenarios.find(x=>x.id===U.modal.id).ctas.splice(+a.slice(6),1);render();return}if(a.startsWith("save-scenario:")){saveScenario(a.slice(14));return}if(a.startsWith("save-project")){saveProject();return}if(a==="save-content"){saveContent();return}if(a==="save-new-scenario"){saveScenarioNew();return}if(a==="save-new-story"){saveStory();return}if(a.startsWith("save-campaign:")){saveCampaign(a.slice(14));return}if(a.startsWith("edit-campaign:")){U.modal={type:"new-campaign",id:a.slice(14)};render();return}if(a==="add-member"){U.modal={type:"add-member"};render();return}if(a.startsWith("save-member:")){saveMember(a.slice(12));return}if(a==="notif-toggle"){S.notificationsEnabled=!S.notificationsEnabled;commit("Notification setting saved");return}if(a==="analytics-add"){let id=PC()[0]?.id;if(id)U.modal={type:"analytics",id},render();return}if(a.startsWith("save-analytics:")){saveAnalytics(a.slice(15));return}if(a==="run-compare"){toast("Comparison generated");return}if(a==="print"){window.print();return}if(a==="ai"){toast("AI Mock action");return}if(a==="export-json"){download("content-control-center-backup.json",JSON.stringify(S,null,2),"application/json");return}if(a==="export-csv"){download("project.csv",csv(PC().map(c=>({Title:c.title,Status:c.status,Deadline:c.deadline,PublishDate:c.publishDate,Responsible:S.users.find(u=>u.id===c.responsibleId)?.name||"",Type:c.type}))),"text/csv");return}if(a==="export-calendar"){download("calendar.csv",csv(PC().map(c=>({Title:c.title,Deadline:c.deadline,PublishDate:c.publishDate,Status:c.status}))),"text/csv");return}if(a==="export-analytics"){download("analytics.csv",csv(S.analytics.map(a=>({Content:S.content.find(c=>c.id===a.contentId)?.title||a.contentId,D7Views:a.metrics?.D7?.Views||0,D7Reach:a.metrics?.D7?.Reach||0}))),"text/csv");return}if(a==="import-json"){let i=document.createElement("input");i.type="file";i.accept=".json";i.onchange=e=>{let f=e.target.files?.[0];if(!f)return;let r=new FileReader();r.onload=()=>{try{S=JSON.parse(r.result);save();render();toast("Imported")}catch{toast("Invalid JSON")}};r.readAsText(f)};i.click();return}if(a==="reset"){confirmAct("Reset MVP","تمام داده‌های این مرورگر reset شود؟",()=>{S=structuredClone(SEED);save();render();toast("Reset complete")});return}if(a.startsWith("open-notif:")){let n=S.notifications.find(x=>x.id===a.slice(12));if(n)n.read=true;U.modal=n?.targetType==="content"?{type:"content",id:n.targetId}:null;save();render();return}if(a.startsWith("user-select")){return}}
function confirmAct(title,text,cb){if(confirm(title+"\n\n"+text))cb()}
function changeStatus(id,st){let c=S.content.find(x=>x.id===id);if(!c||!perm("production"))return;confirmAct("Change Status",`${c.title} → ${st}`,()=>{let old=c.status;c.status=st;c.completedStages=WORK.slice(0,WORK.indexOf(st)+1);log(`Status changed: ${old} → ${st}`,c.projectId);notify(`Status تغییر کرد: ${c.title}`,c.id);commit("Status updated")})}
function archive(id,on){let p=S.projects.find(x=>x.id===id);if(!p||!manager())return;confirmAct(on?"Archive Project":"Unarchive Project",p.name,()=>{p.archived=on;log(on?"Project archived":"Project unarchived",id);commit(on?"Archived":"Unarchived")})}
function duplicate(id){let c=S.content.find(x=>x.id===id);if(!c||!manager())return;let n=structuredClone(c);n.id="CNT-"+Date.now();n.title+= " — Copy";n.status="Scenario Ready";S.content.unshift(n);log("Content duplicated",c.projectId);commit("Duplicated")}
function saveProject(){let p={id:"PRJ-"+Date.now(),name:document.querySelector('[data-p="name"]').value,description:document.querySelector('[data-p="description"]').value,logo:document.querySelector('[data-p="logo"]').value,color:document.querySelector('[data-p="color"]').value,archived:false,contentTypes:[...CTYPES]};S.projects.push(p);S.users.find(u=>u.id===S.currentUserId).projects.push(p.id);log("Project created",p.id);S.selectedProjectId=p.id;U.projectId=p.id;U.modal=null;commit("Project created")}
function saveContent(){let title=document.querySelector('[data-c="title"]').value.trim();if(!title)return toast("Title required");let c={id:"CNT-"+Date.now(),projectId:U.projectId,title,type:document.querySelector('[data-c="type"]').value,status:document.querySelector('[data-c="status"]').value,deadline:document.querySelector('[data-c="deadline"]').value,publishDate:document.querySelector('[data-c="publishDate"]').value,responsibleId:document.querySelector('[data-c="responsibleId"]').value,scenarioId:null,roles:[],archived:false,productionLinks:[],comments:[],editorNotes:[],publishTime:"",postUrl:""};S.content.unshift(c);log("Content created");U.modal=null;commit("Content created")}
function saveScenarioNew(){let title=document.querySelector('[data-ns="title"]').value.trim();if(!title)return toast("Title required");let id="SCN-"+Date.now(),s={id,projectId:U.projectId,contentId:null,title,contentType:document.querySelector('[data-ns="contentType"]').value,goal:document.querySelector('[data-ns="goal"]').value,platform:document.querySelector('[data-ns="platform"]').value,publishDate:document.querySelector('[data-ns="publishDate"]').value,audience:document.querySelector('[data-ns="audience"]').value,contentPillar:document.querySelector('[data-ns="contentPillar"]').value,status:"Draft",progress:0,responsibleId:document.querySelector('[data-ns="responsibleId"]').value,hooks:[document.querySelector('[data-ns="hook"]').value||"هوک"],body:{mainScript:document.querySelector('[data-ns="body"]').value||"",storyFlow:"Hook → Body → CTA",keyMessage:"",brandMention:P().name},ctas:[document.querySelector('[data-ns="cta"]').value||"برای مشاوره دایرکت بده"],publishing:{caption:"",coverText:"",hashtags:"",notes:""},production:{speaker:"",shotList:[],editorNotes:[],assetLinks:[]},light:"",notes:""};S.scenarios.unshift(s);log("Scenario created");U.modal=null;commit("Scenario created")}
function saveScenario(id){let s=S.scenarios.find(x=>x.id===id);if(!s)return;s.title=document.querySelector('[data-sf="title"]')?.value||s.title;s.contentType=document.querySelector('[data-sf="contentType"]')?.value||s.contentType;s.goal=document.querySelector('[data-sf="goal"]')?.value||s.goal;s.platform=document.querySelector('[data-sf="platform"]')?.value||s.platform;s.publishDate=document.querySelector('[data-sf="publishDate"]')?.value||s.publishDate;s.audience=document.querySelector('[data-sf="audience"]')?.value||s.audience;s.contentPillar=document.querySelector('[data-sf="contentPillar"]')?.value||s.contentPillar;s.responsibleId=document.querySelector('[data-sf="responsibleId"]')?.value||s.responsibleId;s.hooks=[...document.querySelectorAll('[data-hook]')].map(x=>x.value.trim()).filter(Boolean);s.ctas=[...document.querySelectorAll('[data-cta]')].map(x=>x.value.trim()).filter(Boolean);s.body.mainScript=document.querySelector('[data-body="mainScript"]').value;s.body.storyFlow=document.querySelector('[data-body="storyFlow"]').value;s.body.keyMessage=document.querySelector('[data-body="keyMessage"]').value;s.body.brandMention=document.querySelector('[data-body="brandMention"]').value;s.publishing.caption=document.querySelector('[data-pub="caption"]').value;s.publishing.coverText=document.querySelector('[data-pub="coverText"]').value;s.publishing.hashtags=document.querySelector('[data-pub="hashtags"]').value;s.publishing.notes=document.querySelector('[data-pub="notes"]').value;s.production.speaker=document.querySelector('[data-prod="speaker"]').value;s.production.editorNotes=document.querySelector('[data-prod="editorNotes"]').value.split("\n").filter(Boolean);log("Scenario updated",s.projectId);commit("Scenario saved")}
function saveStory(){let s={id:"ST-"+Date.now(),projectId:U.projectId,title:document.querySelector('[data-st="title"]').value,status:document.querySelector('[data-st="status"]').value,deadline:document.querySelector('[data-st="deadline"]').value,publishDate:document.querySelector('[data-st="publishDate"]').value,responsibleId:document.querySelector('[data-st="responsibleId"]').value,contentId:document.querySelector('[data-st="contentId"]').value||null};S.stories.unshift(s);log("Story created");U.modal=null;commit("Story created")}
function saveCampaign(id){let c=id?S.campaigns.find(x=>x.id===id):{id:"CAM-"+Date.now(),projectId:U.projectId};c.title=document.querySelector('[data-ca="title"]').value;c.status=document.querySelector('[data-ca="status"]').value;c.startDate=document.querySelector('[data-ca="startDate"]').value;c.endDate=document.querySelector('[data-ca="endDate"]').value;c.contentIds=[...document.querySelectorAll('[data-ca-content]:checked')].map(x=>x.dataset.caContent);if(!id)S.campaigns.unshift(c);log(id?"Campaign updated":"Campaign created");U.modal=null;commit("Campaign saved")}
function saveMember(id){let u=id?S.users.find(x=>x.id===id):{id:"USR-"+Date.now()};u.name=document.querySelector('[data-m="name"]').value;u.email=document.querySelector('[data-m="email"]').value;u.roles=[...document.querySelector('[data-m="roles"]').selectedOptions].map(o=>o.value);u.projects=[...document.querySelector('[data-m="projects"]').selectedOptions].map(o=>o.value);if(!id)S.users.push(u);log(id?"Member updated":"Member added");U.modal=null;commit("Member saved")}
function saveAnalytics(id){let a=S.analytics.find(x=>x.contentId===id);if(!a)a={contentId:id,metrics:{},notes:[]},S.analytics.push(a);["D0","D1","D3","D7","D30"].forEach(d=>{a.metrics[d]=a.metrics[d]||{};S.customMetrics.forEach(m=>{a.metrics[d][m]=Number(document.querySelector(`[data-metric="${d}|${m}"]`)?.value||0)})});let note=document.querySelector('[data-anote]')?.value;if(note)a.notes.push({userName:cur().name,date:jp(new Date()),time:fmtTime(),text:note});log("Analytics updated");U.modal=null;commit("Analytics saved")}
function csv(rows){if(!rows.length)return "";let keys=Object.keys(rows[0]);return [keys.join(","),...rows.map(r=>keys.map(k=>`"${String(r[k]??"").replaceAll('"','""')}"`).join(","))].join("\n")}function download(name,data,type){let a=document.createElement("a");a.href=URL.createObjectURL(new Blob([data],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),400)}
setInterval(()=>{let e=document.querySelector('.date b');if(e)e.textContent=fmtTime()},1000);render();
})();